250	/// Adapter for reversing iterators conditionally.
251	pub trait MaybeReverseIter {
252	    type RevIfIter;
253	
254	    /// Reverse this iterator (apply `.rev()`) based on some condition.
255	    fn rev_if(self, condition: bool) -> Self::RevIfIter
256	    where
257	        Self: Sized;
258	}
