        test(&[('a', 1), ('a', 2), ('a', 3), ('b', 2)], &[('a', 3), ('b', 2)]);
        test(&[('b', 2), ('c', 3), ('c', 4)], &[('b', 2), ('c', 4)]);
        test(
            &[('a', 1), ('b', 1), ('c', 1), ('c', 2), ('d', 1)],
            &[('a', 1), ('b', 1), ('c', 2), ('d', 1)],
        );
    }
